// One id for everything this business owns: its clients row, its inventory
// and its WhatsApp instance. Short, readable, and unique.
const f = $('Add a Business').first().json;
const slug = String(f.business_name || 'business').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 24) || 'business';
const id = slug + '_' + Math.random().toString(36).slice(2, 6);
const numbers = String(f.alert_numbers || '').split(/[,;\s]+/).map((n) => n.replace(/\D/g, '').replace(/^0(\d{10})$/, '234$1')).filter((n) => n.length >= 8);
const TONES = {
  'Friendly & warm': 'Friendly and warm, like a helpful shop attendant who knows the customer.',
  'Professional': 'Professional, polite and concise.',
  'Fun & playful': 'Fun and playful, with the odd emoji, but always clear.',
  'Friendly, Nigerian English & Pidgin welcome': 'Friendly Nigerian English; if the customer writes in Pidgin, reply in Pidgin.',
};
const services = String(f.services || '').split('\n').map((l) => l.trim()).filter(Boolean).map((l) => {
  const [name, price, stock, link, desc] = l.split('|').map((x) => (x || '').trim());
  return {
    item_name: name,
    price: Number(String(price || '').replace(/[^0-9.]/g, '')) || null,
    quantity: stock === '' || stock === undefined ? 100 : Number(String(stock).replace(/[^0-9]/g, '')) || 0,
    payment_url: /^https?:\/\//.test(link || '') ? link : null,
    description: desc || null,
  };
}).filter((s) => s.item_name);
return [{ json: {
  client_id: id,
  instance_name: id,
  business_name: String(f.business_name).trim(),
  alert_numbers: '{' + numbers.join(',') + '}',
  first_alert: numbers[0] || '',
  alert_email: f.alert_email || null,
  website: String(f.website || '').trim() || null,
  tagline: String(f.tagline || '').trim() || null,
  about: String(f.about || '').trim(),
  faqs: String(f.faqs || '').trim() || null,
  tone: TONES[f.tone] || null,
  currency: f.currency || 'NGN',
  services,
} }];

// One item per product or service, tagged with the new business.
const b = $('Prepare Business').first().json;
return b.services.map((s) => ({ json: { ...s, client_id: b.client_id } }));
